            Ok(files) => {
                live.stamps = Some(stamps::record(files.into_iter().map(Utf8PathBuf::from).collect(), live.read_from))
            }
            Err(error) => {
                tracing::debug!(%error, "could not list the snapshot's files; the next request builds a fresh one");
