307	/// ADR 0026 S4: how long a story waits for the checker's answer through the Rust client. Each run opens a fresh session
308	/// as the addon does (the checker started in the background at creation), waits until that process is up, then asks for
309	/// `key` once and times the whole answer: the structural pass and the checker's program and conversion for the
310	/// component. Passes when every answer is the checker's and the median is at most `budget_ms`, the addon's default
311	/// `semanticWaitMs`.
312	fn first_answer(src: &Utf8PathBuf, tsc: &str, key: &str, runs: usize, budget_ms: u128) -> bool {
313	    let (mut start, mut first, mut structural, mut answered) = (Vec::new(), Vec::new(), Vec::new(), 0);
314	    for _ in 0..runs.max(1) {
315	        let plain = WatchSession::lazy(PipelineOptions {
316	            src_dirs: vec![src.clone()],
317	            load_dependencies: true,
318	            collapse_inherited_props: CollapseInheritedProps::None,
319	            ..PipelineOptions::default()
320	        });
321	        drop(plain.initialize());
322	        let began = Instant::now();
323	        drop(plain.component(key).expect("the key is a component"));
324	        structural.push(began.elapsed().as_millis());
325	
326	        let (session, checker) = open(src, tsc, Vec::new(), None);
327	        let began = Instant::now();
328	        checker.warm_up();
329	        // Queued behind the warm-up, an empty request returns once the process is up and initialized.
330	        drop(checker.request(Vec::new()).recv_timeout(Duration::from_secs(120)));
331	        start.push(began.elapsed().as_millis());
332	        let began = Instant::now();
333	        let answer = session.component(key).expect("the key is a component");
334	        first.push(began.elapsed().as_millis());
335	        answered += usize::from(by_checker(&answer));
336	    }
337	    let median = |values: &mut Vec<u128>| {
338	        values.sort_unstable();
339	        values[values.len() / 2]
340	    };
341	    let (start_ms, first_ms, structural_ms) = (median(&mut start), median(&mut first), median(&mut structural));
342	    let ok = answered == first.len() && first_ms <= budget_ms;
343	    println!(
344	        "{{\"gate\":\"first-answer\",\"component\":{key:?},\"runs\":{},\"answeredByChecker\":{answered},\"startMs\":{start_ms},\"structuralMs\":{structural_ms},\"firstAnswerMs\":{first_ms},\"firstAnswerEachMs\":{first:?},\"budgetMs\":{budget_ms},\"ok\":{ok}}}",
345	        first.len(),
346	    );
347	    ok
348	}
