import { fileURLToPath } from 'node:url'
import type { DocgenProviderDescriptor } from 'storybook/internal/types'
import type { CaliperStorybookOptions } from './index.js'
import { assertValidOptions } from './validate.js'
import { OPTION_KEYS } from './option-keys.js'

/** The addon's options travel to the docgen worker by structured clone, so only these plain fields go. */
function workerOptions(options: CaliperStorybookOptions): CaliperStorybookOptions {
  return Object.fromEntries(OPTION_KEYS.map((key) => [key, options[key]]))
}

/** Registered last, the provider wraps React's: it answers first and hands on what it can't document. */
export const experimental_docgenProvider = (
  existing: DocgenProviderDescriptor[] = [],
  options: CaliperStorybookOptions = {},
): DocgenProviderDescriptor[] => {
  assertValidOptions(options)
  return [
    ...existing,
    { moduleSpecifier: fileURLToPath(new URL('provider.js', import.meta.url)), options: workerOptions(options) },
  ]
}

/** Storybook runs docgen providers only with `features.docgenServer`, which this turns on unless `main.ts` sets it. */
export const isDocgenProviderEnabled = (): boolean => true
export interface CaliperStorybookOptions {
  /** Directories caliper-docgen extracts from, relative to Storybook's working directory. Default: `['src']`. */
  srcDirs?: string[]
  exclude?: string[]
  tsconfigPath?: string
  /** Leave out the HTML attributes a component inherits from its element. Same as `htmlAttributes: 'none'`. */
  skipHtmlProps?: boolean
  /**
   * Which HTML attributes a component inherits from its element to list: `'full'` (all of them, the default),
   * `'curated'` (a compact subset: handlers, `aria-*`, `ref`, common attributes) or `'none'`. Wins over `skipHtmlProps`.
   */
  htmlAttributes?: 'curated' | 'full' | 'none'
  /**
   * Read and write the on-disk caches under `node_modules/.cache`. Default: `true`; `false` reads and writes nothing
   * there and parses everything every run. The output is the same.
   */
  cache?: boolean
  /**
   * Load the type declarations your props reference from installed packages, so props typed by a library resolve
   * instead of degrading. Default: `true`; `false` skips the extra work.
   */
  loadDependencies?: boolean
