133	fn determinism(src: &Utf8PathBuf, tsc: &str, components: usize, threads: &[String], runs: usize) -> bool {
134	    let (probe, _checker) = open(src, tsc, Vec::new(), None);
135	    let mut keys = probe.component_keys();
136	    keys.retain(|key| key != "GateEdited");
137	    keys.sort();
138	    let step = (keys.len() / components.max(1)).max(1);
139	    let keys: Vec<String> = keys.into_iter().step_by(step).take(components).collect();
140	    drop(probe);
141	    let mut reference: Option<String> = None;
142	    let (mut ok, mut variants) = (true, Vec::new());
143	    for count in threads {
144	        for run in 0..runs {
145	            let env = vec![("RAYON_NUM_THREADS".to_string(), count.clone())];
146	            let (session, checker) = open(src, tsc, env, None);
147	            let mut order = keys.clone();
148	            if run % 2 == 1 {
149	                order.reverse();
150	            }
151	            let (mut text, mut structural, mut most_threads) = (Vec::new(), Vec::new(), 0);
152	            for key in &order {
153	                let answer = session.component(key).expect("a sampled key is a component");
154	                if !by_checker(&answer) {
155	                    structural.push(key.clone());
156	                }
157	                text.push((
158	                    key.clone(),
159	                    format!("{}\n{:?}", serde_json::to_string(&answer.entry).unwrap(), answer.diagnostics),
160	                ));
161	                if let Some((_, count)) = checker.process_id().and_then(process_stats) {
162	                    most_threads = most_threads.max(count);
163	                }
164	            }
165	            text.sort();
166	            let bytes = text.iter().map(|(key, body)| format!("{key}\n{body}\n")).collect::<String>();
167	            let same = reference.get_or_insert_with(|| bytes.clone()) == &bytes;
168	            // A component the checker declines keeps its structural answer; that is deterministic too, and is listed.
169	            ok &= same;
170	            structural.sort();
171	            variants.push(format!(
172	                "{{\"threads\":{count},\"run\":{run},\"reversed\":{},\"bytes\":{},\"answeredByChecker\":{},\"structuralOnly\":{structural:?},\"maxProcessThreads\":{most_threads},\"equalsFirst\":{same}}}",
173	                run % 2 == 1,
174	                bytes.len(),
175	                order.len() - structural.len()
176	            ));
177	        }
178	    }
179	    println!(
180	        "{{\"gate\":\"determinism\",\"components\":{},\"variants\":[{}],\"ok\":{ok}}}",
181	        keys.len(),
182	        variants.join(",")
183	    );
184	    ok
185	}
