187	fn percentile(sorted: &[f64], at: f64) -> f64 {
188	    let index = ((sorted.len() as f64 * at).ceil() as usize).clamp(1, sorted.len().max(1)) - 1;
189	    sorted.get(index).copied().unwrap_or(0.0)
190	}
