192	/// Each answer's JSON entry and diagnostics, in `keys` order.
193	fn answer_bytes(session: &WatchSession, keys: &[String]) -> Vec<String> {
194	    keys.iter()
195	        .map(|key| {
196	            let answer = session.component(key).expect("a sampled key is a component");
197	            format!("{key}\n{}\n{:?}", serde_json::to_string(&answer.entry).unwrap(), answer.diagnostics)
198	        })
199	        .collect()
