211	/// ADR 0026 S6: edit-and-query on the kept snapshot. Rewrites one component's file (`ButtonProps & { edit{n}: string }`),
212	/// applies it with `update_file`, which tells the checker, and times that and the component's answer, `--edits` times,
213	/// sampling the checker's resident memory after each. Then it times the checker's answer alone on its unchanged
214	/// snapshot, and byte-compares the edited component and every `--sample`th other component with a fresh session asked
215	/// in reverse order. Passes when every answer is the checker's, carries its edit and no warning, memory stays under
216	/// `--max-rss-mib`, the bytes match, and the p95 is at most `--budget-ms`. `--props own` edits a component with one prop
217	/// of its own in the same program instead ([`own_props_source`]).
218	fn watch(src: &Utf8PathBuf, tsc: &str, run: WatchRun) -> bool {
219	    let WatchRun { edits, sample, budget_ms, max_rss_mib, own_props } = run;
220	    let source = if own_props { own_props_source } else { edit_source };
221	    let file = src.join("GateEdited.tsx");
222	    std::fs::write(&file, source(0)).unwrap();
223	    let (session, checker) = open(src, tsc, Vec::new(), max_rss_mib);
224	    let threshold = max_rss_mib.unwrap_or(OnDemandConfig::new(src.clone()).max_rss_mib);
225	    drop(session.component("GateEdited").expect("GateEdited is a component"));
226	    let (mut times, mut updates, mut processes, mut peak) = (Vec::new(), Vec::new(), BTreeSet::new(), 0);
227	    let (mut answered, mut stale, mut warned) = (0, 0, 0);
228	    // CPU time is what an edit costs whatever else the machine runs: the checker's, each process's last reading.
229	    let (own_cpu, first) = (cpu_ms(std::process::id()), checker.process_id());
230	    let first_cpu = first.and_then(cpu_ms).unwrap_or(0.0);
231	    let mut checker_cpu = std::collections::BTreeMap::new();
232	    for n in 1..=edits {
233	        std::fs::write(&file, source(n)).unwrap();
234	        let began = Instant::now();
235	        session.update_file(&file);
236	        updates.push(began.elapsed().as_secs_f64() * 1000.0);
237	        let answer = session.component("GateEdited").expect("GateEdited is a component");
238	        times.push(began.elapsed().as_secs_f64() * 1000.0);
239	        answered += usize::from(by_checker(&answer));
240	        stale += usize::from(!answer.entry.props.contains_key(&format!("edit{n}")));
241	        warned += usize::from(answer.diagnostics.iter().any(|d| d.severity == DiagnosticSeverity::Warning));
242	        if let Some(pid) = checker.process_id() {
243	            processes.insert(pid);
244	            peak = peak.max(process_stats(pid).map_or(0, |(mib, _)| mib));
245	            if let Some(ms) = cpu_ms(pid) {
246	                checker_cpu.insert(pid, ms);
247	            }
248	        }
249	    }
250	    let checker_cpu = (checker_cpu.values().sum::<f64>() - first_cpu) / edits as f64;
251	    let own_cpu = own_cpu.zip(cpu_ms(std::process::id())).map_or(0.0, |(start, end)| (end - start) / edits as f64);
252	    let snapshots = checker.snapshots();
253	
254	    // The checker's answer alone: the same request the session sends, on the snapshot it keeps, nothing changed.
255	    let entry = session.component("GateEdited").unwrap().entry;
256	    let target = SemanticTarget {
257	        key: "GateEdited".to_string(),
258	        file_path: entry.file_path.clone(),
259	        display_name: entry.display_name.clone(),
260	        exports: entry.exports.clone(),
261	        described: entry.props.values().filter(|p| !p.description.is_empty()).map(|p| p.name.clone()).collect(),
262	        react_wanted: react_props_wanted(session.options.html_attributes, &entry.props),
263	    };
264	    let mut query = Vec::new();
265	    for _ in 0..21 {
