//! Scratch measurements for "how fast do a story's checker props arrive" (ADR 0026 S4/S8). Not part of the repo.
//!
//!   storyprops cold     --src DIR --tsc PATH --key K [--runs 5] [--wait-ms 120000]
//!   storyprops percomp  --src DIR --tsc PATH --keys A,B,C [--runs 3]
//!   storyprops batch    --src DIR --tsc PATH --keys A,B,C [--runs 3]
//!   storyprops prefetch --src DIR --tsc PATH --prefetch A,B,C --story S --gap-ms G [--runs 3]
//!   storyprops sizes    --src DIR --tsc PATH [--every 20]
use std::process::Command;
use std::sync::Arc;
use std::time::{Duration, Instant};

use caliper_docgen_core::pipeline::{CollapseInheritedProps, ComponentAnswer, PipelineOptions, WatchSession};
use caliper_docgen_core::react_types::react_props_wanted;
use caliper_docgen_core::types::semantic::{SemanticProvider, SemanticTarget};
use caliper_docgen_semantic::{OnDemand, OnDemandConfig};
use camino::Utf8PathBuf;

const CHECKER_NOTE: &str = "resolved by the TypeScript checker";

fn arg(args: &[String], name: &str) -> Option<String> {
    args.iter().position(|a| a == name).and_then(|at| args.get(at + 1)).cloned()
}

fn options(src: &Utf8PathBuf) -> PipelineOptions {
    PipelineOptions {
        src_dirs: vec![src.clone()],
        load_dependencies: true,
        collapse_inherited_props: CollapseInheritedProps::None,
        ..PipelineOptions::default()
    }
}

/// As the binding's `new_session` + `on_demand_checker`: the checker is started in the background at creation.
fn open(src: &Utf8PathBuf, tsc: &str, tsconfig: Option<Utf8PathBuf>, wait: Duration) -> (WatchSession, Arc<OnDemand>) {
    let mut config = OnDemandConfig::new(src.clone());
    config.tsconfig = tsconfig.or_else(|| src.ancestors().map(|dir| dir.join("tsconfig.json")).find(|f| f.is_file()));
    config.tsc_path = Some(Utf8PathBuf::from(tsc));
    config.request_timeout = Duration::from_secs(120);
    let checker = OnDemand::new(config);
    checker.warm_up();
    let checker = Arc::new(checker);
    let session = WatchSession::lazy(options(src)).with_semantic(checker.clone(), wait);
    (session, checker)
}

fn by_checker(answer: &ComponentAnswer) -> bool {
    answer.diagnostics.iter().any(|d| d.message.contains(CHECKER_NOTE))
}

fn rss_mib(pid: u32) -> u64 {
    Command::new("ps")
        .args(["-o", "rss=", "-p", &pid.to_string()])
        .output()
        .ok()
        .and_then(|o| String::from_utf8_lossy(&o.stdout).trim().parse::<u64>().ok())
        .map_or(0, |kib| kib / 1024)
}

fn self_rss_mib() -> u64 {
    rss_mib(std::process::id())
}

fn ms(since: Instant) -> f64 {
    since.elapsed().as_secs_f64() * 1000.0
}

fn target_of(session: &WatchSession, answer: &ComponentAnswer) -> SemanticTarget {
    let entry = &answer.entry;
    SemanticTarget {
        key: answer.key.clone(),
        file_path: entry.file_path.clone(),
        display_name: entry.display_name.clone(),
        exports: entry.exports.clone(),
        described: entry.props.values().filter(|p| !p.description.is_empty()).map(|p| p.name.clone()).collect(),
        react_wanted: react_props_wanted(session.options.html_attributes, &entry.props),
    }
}

/// Structural answers (no checker), to build targets from.
