// getPropertiesOfType, using getConstraintTypeOfMappedType? Scratch, not part of the repo.
import { Client } from '/Users/gabe/Projects/caliper/.claude/worktrees/agent-a55b6d9cb48f258fa/node_modules/.pnpm/tsrs@0.23.0-ts7.1.0-beta/node_modules/tsrs/dist/api/async/client.js'

const root = '/Users/gabe/Projects/caliper-fixtures/gate-large'
const file = `${root}/src/${process.argv[3] ?? 'ChakraButton'}.tsx`
const client = new Client({ tsserverPath: process.argv[2], cwd: root })
await client.connect()
const call = (m, p) => client.apiRequest(m, p)
const bytes = (v) => JSON.stringify(v ?? null).length

await call('initialize', null)
const options = (await call('parseConfigFile', { file: `${root}/tsconfig.json` })).options
let s = performance.now()
const snap = await call('createSnapshot', { createPrograms: [{ rootFiles: [file], compilerOptions: options }] })
console.log('createSnapshot ms', (performance.now() - s).toFixed(1))
const sc = { snapshot: snap.snapshot, project: snap.projects[0].id }
const mod = await call('getSymbolOfSourceFile', { ...sc, file })
const [comp] = await call('getExportsOfModule', { ...sc, symbol: mod.reference ?? mod.id })
const ty = await call('getTypeOfSymbol', { ...sc, symbol: comp.reference ?? comp.id })
const [sig] = await call('getSignaturesOfType', { ...sc, type: ty.id, kind: 0 })
const [param] = await call('getParametersOfSignature', { ...sc, objectId: sig.id })
const pty = await call('getTypeOfSymbol', { ...sc, symbol: param.reference ?? param.id })
const props = await call('getPropertiesOfType', { ...sc, type: pty.id })
console.log('props', props.length)
const types = await call('getTypesOfSymbols', { ...sc, symbols: props.map((p) => p.reference ?? p.id) })

const mapped = new Map() // type id -> info
const seen = new Set()
async function walk(t, depth) {
  if (!t || seen.has(t.id) || depth > 3) return
  seen.add(t.id)
  if (t.flags & 1048576 /* Union */) {
    for (const m of await call('getTypesOfType', { ...sc, type: t.id })) await walk(m, depth + 1)
  } else if (t.flags & 524288 /* Object */ && t.objectFlags & 32 /* Mapped */) {
    mapped.set(t.id, t)
  }
}
for (const t of types) await walk(t, 0)
console.log('distinct mapped object types reached from the props (depth<=3)', mapped.size)

let [propsMs, propsBytes, propsCount, consMs, consBytes] = [0, 0, 0, 0, 0]
const constraints = new Map()
let sample
for (const [id] of mapped) {
  s = performance.now()
  const list = await call('getPropertiesOfType', { ...sc, type: id })
  propsMs += performance.now() - s
  propsBytes += bytes(list)
  propsCount += list.length
  s = performance.now()
  const c = await call('getConstraintTypeOfMappedType', { ...sc, type: id })
  const n = await call('getNameTypeOfMappedType', { ...sc, type: id })
  consMs += performance.now() - s
  consBytes += bytes(c) + bytes(n)
  const key = c?.id
  if (!constraints.has(key)) constraints.set(key, { c, n, count: list.length, decl: list[0]?.declarations?.[0] })
  else if (constraints.get(key).count !== list.length) console.log('MISMATCH: same constraint, different count', key)
  sample ??= { id, list0: list[0], c, n }
}
console.log('getPropertiesOfType over them: ms', propsMs.toFixed(1), 'bytes', propsBytes, 'properties', propsCount)
console.log('constraint+nameType over them: ms', consMs.toFixed(1), 'bytes', consBytes)
console.log('distinct constraint types', constraints.size)
for (const [key, v] of constraints) {
  s = performance.now()
  const members = v.c && v.c.flags & 1048576 ? await call('getTypesOfType', { ...sc, type: v.c.id }) : null
  console.log(' constraint', key, 'flags', v.c?.flags, 'nameType', v.n?.id ?? null, 'props', v.count,
    'union members', members?.length ?? '-', 'ms', (performance.now() - s).toFixed(1), 'first decl', v.decl)
}
console.log('sample', JSON.stringify(sample).slice(0, 600))
await client.close?.()
process.exit(0)

