const sc = { snapshot: snap.snapshot, project: snap.projects[0].id }
const mod = await call('getSymbolOfSourceFile', { ...sc, file })
const [comp] = await call('getExportsOfModule', { ...sc, symbol: mod.reference ?? mod.id })
const ty = await call('getTypeOfSymbol', { ...sc, symbol: comp.reference ?? comp.id })
const [sig] = await call('getSignaturesOfType', { ...sc, type: ty.id, kind: 0 })
const [param] = await call('getParametersOfSignature', { ...sc, objectId: sig.id })
const pty = await call('getTypeOfSymbol', { ...sc, symbol: param.reference ?? param.id })
const props = await call('getPropertiesOfType', { ...sc, type: pty.id })
const color = props.find(p => p.name === 'color')
console.log('prop', JSON.stringify(color).slice(0, 300))
const [t] = await call('getTypesOfSymbols', { ...sc, symbols: [color.reference ?? color.id] })
console.log('type', JSON.stringify(t).slice(0, 400))
console.log('text', await call('typeToString', { ...sc, type: t.id }))
const members = await call('getTypesOfType', { ...sc, type: t.id })
for (const m of members) console.log(' member', JSON.stringify(m).slice(0, 300))
process.exit(0)
EOF
